const KEY='gamehub-steam-demo-v1';const LEGAL_VERSION=2;const FLOW_VERSION=3;const LEGAL_BODY=__LEGAL__;const escapeHtml=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\"','&quot;');
