const bar=(title,action='back')=>'<div class="bar"><button class="iconbtn" data-action="'+action+'" aria-label="返回">'+ic('back')+'</button><h2>'+title+'</h2></div>';
function navPortrait(){return '<nav class="nav-p" aria-label="盖世导航">'+[['home','首页','home'],['chat','社区','community'],['rank','排行榜',null],['grid','游戏库','library'],['user','我的','profile']].map(([icon,t,action])=>'<button '+(action?'data-action="'+action+'"':'disabled title="本次不演示"')+' class="'+(state.page===action?'active':'')+'">'+ic(icon)+'<span>'+t+'</span></button>').join('')+'</nav>'}
function entryCards(){return '<div class="entries"><button class="entry" data-action="enter-steam" data-testid="steam-entry">'+renderAccountEntry()+'</button><button class="entry" disabled title="保留原入口，本次不演示"><span class="epic-brand">'+EPIC+'</span><span>Epic</span></button><button class="entry" disabled title="保留原入口，本次不演示"><span class="plus">＋</span><span>导入游戏</span></button></div>'}
function renderLibrary(){if(state.orientation==='landscape')return '<div class="l-nav"><strong>'+ic('grid')+'游戏库</strong><div class="dim">'+ic('home')+ic('chat')+ic('rank')+'</div><div class="right"><button class="iconbtn" data-action="settings" aria-label="设置">'+ic('gear')+'</button><span>09:41</span><i class="battery"></i></div></div><div class="main-content l-library"><section><div class="recent-title">最近游戏</div><div class="recent-row">'+games.slice(0,3).map(g=>'<button class="recent-card" data-action="launch-host-game" data-game="'+g.id+'"><img src="'+ASSETS[g.id]+'" alt="'+g.name+'封面"><strong>'+g.name+'</strong></button>').join('')+'</div><p class="muted" style="margin:12px 0 0;font-size:11px">我的游戏 · 本机已下载</p></section><section class="l-side"><div class="tabs" style="padding:0 0 17px;font-size:14px"><span class="current">PC游戏</span><span class="off" style="font-size:13px">复古游戏</span></div>'+entryCards()+'</section></div><div class="l-foot"><span>当前选择：游戏库</span><span>LB / RB 切换页面　 A 确认　 B 返回</span></div>';
return stamp()+'<div class="main-content library"><div class="tabs"><span class="current">PC游戏</span><span class="off">复古游戏</span><button class="iconbtn" disabled aria-label="设备">'+ic('device')+'</button></div>'+entryCards()+'<div class="section-label"><h3>我的游戏</h3><span class="count">2款</span><div class="tools"><button disabled aria-label="搜索">'+ic('search')+'</button><button disabled aria-label="引擎设置">'+ic('gear')+'</button><button disabled>最近游玩</button></div></div><div class="game-grid">'+games.slice(0,2).map(g=>'<button class="gamecard" data-action="launch-host-game" data-game="'+g.id+'"><img src="'+ASSETS[g.id]+'" alt="'+g.name+'封面"><h4>'+g.name+'</h4><p>'+(g.id==='hades'?'已导入':'本机已下载')+'</p></button>').join('')+'</div></div>'+navPortrait()+gesture()}
