function modeCard(mode,title,desc){return '<button class="mode-card" role="radio" aria-checked="'+(state.selection===mode)+'" data-action="select-mode" data-mode="'+mode+'"><span class="mode-icon">'+ic(mode==='gamepad'?'gamepad':'monitor')+'</span><span><strong>'+title+'</strong><small>'+desc+'</small></span><span class="radio"></span></button>'}
function renderMode(){return stamp()+bar('Steam 启动模式')+'<section class="flow mode-page"><div class="flow-body"><div><div class="mode-list" role="radiogroup" aria-label="Steam启动模式">'+modeCard('gamepad','大屏模式','大卡片，适合手柄操作')+modeCard('window','窗口模式','桌面式界面，适合触屏 / 鼠标')+'</div><label class="remember-row"><span class="remember-copy"><span>记住我的选择</span><small>可在设置中修改启动模式</small></span><input type="checkbox" role="switch" aria-label="记住我的选择" id="remember" '+(state.remember?'checked':'')+'></label></div></div><div class="mode-actions"><div class="consent-line mode-consent"><input type="checkbox" id="consent" aria-label="同意第三方Steam服务调用免责声明" '+(state.consent?'checked':'')+'><span><label for="consent">我已阅读并同意</label><button class="agreement-link" data-action="read-agreement">《第三方 Steam 服务调用免责声明》</button></span></div><div class="flow-actions"><button class="btn secondary" data-action="library">取消</button><button class="btn primary" data-action="confirm-mode" data-testid="confirm-mode" '+(!state.consent?'disabled':'')+'>继续</button></div></div></section>'+gesture()}
const stageCopy={idle:['准备 Steam','首次使用需要下载运行组件'],metadata:['正在获取包体信息','请稍候，即将开始下载'],downloading:['正在下载运行组件','组件正在下载'],network:['网络连接中断','请检查网络后重试'],storage:['存储空间不足','请释放存储空间后重试'],verifying:['正在校验组件','下载完成，正在检查文件完整性'],verifyError:['组件校验失败','当前文件不可用于启动，请重新准备'],preparing:['正在准备运行环境','请稍候，首次准备可能需要一些时间'],prepareError:['运行环境准备失败','已下载内容保留，可以重试'],starting:['正在启动 Steam','运行组件已就绪，等待 Steam 界面'],startError:['Steam 启动失败','运行环境未能完成初始化']};
function renderPrepare(){const titles={metadata:'准备 Steam',downloading:'下载 Steam 组件',network:'网络连接中断',storage:'存储空间不足',verifying:'正在校验组件',verifyError:'组件校验失败',preparing:'正在准备环境',prepareError:'环境准备失败',starting:'正在启动 Steam',startError:'Steam 启动失败'};const error=['network','storage','verifyError','prepareError','startError'].includes(state.stage);const primary=error?'重试':null;const pending=state.stage==='metadata';const hint={network:'检查网络后重试',storage:'释放空间后重试',verifyError:'请重新下载组件',prepareError:'已保留组件，可重试',startError:'请重试'}[state.stage];return '<div class="prepare-underlay" inert aria-hidden="true">'+renderLibrary()+'</div><div class="overlay prepare-overlay"><section class="modal prepare-modal" role="dialog" aria-modal="true" aria-labelledby="prepareTitle"><div class="prepare-body"><div class="progress-head"><h2 id="prepareTitle">'+(titles[state.stage]||'准备 Steam')+'</h2><strong>'+(pending?'':state.progress+'%')+'</strong></div><div class="track '+(pending?'pending':'')+'"><i style="width:'+state.progress+'%"></i></div><div class="progress-meta"><span>'+(pending?'获取包体信息…':Math.round(state.progress*2.56)+' MB / 256 MB')+'</span></div>'+(hint?'<p class="prepare-error" role="alert">'+hint+'</p>':'')+'</div><div class="prepare-actions"><button class="btn secondary" data-action="library">收起</button>'+(primary?'<button class="btn primary" data-action="download-control" data-testid="download-control">'+primary+'</button>':'')+'</div></section></div>'}
function settingRow(icon,label,value,action,disabled=false){return '<button class="setting-row" '+(disabled?'disabled':'data-action="'+action+'"')+'>'+ic(icon)+'<span>'+label+'</span><span class="value">'+(value||'')+'</span>'+ic('chevron').replace('<svg ','<svg class="chev" ')+'</button>'}
function renderSettings(){return stamp()+bar('设置','settings-back')+'<div class="main-content settings online-settings"><div class="settings-primary group">'+settingRow('device','模式切换',state.orientation==='portrait'?'探索模式':'掌机模式','',true)+settingRow('gift','兑换中心','','',true)+settingRow('bell','通知','','',true)+settingRow('sound','按键音','','',true)+settingRow('shield','隐私设置','','',true)+settingRow('storage','存储管理','','',true)+settingRow('download','下载任务','','',true)+settingRow('steam','Steam 设置','','steam-settings')+settingRow('home','启动后进入',landingLabels[effectiveLanding()],'landing-settings')+'</div><div class="settings-secondary"><div class="group">'+settingRow('chat','帮助与反馈','','',true)+settingRow('info','关于','','',true)+'</div><button class="logout" disabled>退出登录</button></div></div>'+gesture()}
function renderSteamSettings(){let pm={ask:'每次询问',gamepad:'大屏模式',window:'窗口模式'}[pref.preference];return stamp()+bar('Steam 设置','steam-settings-back')+'<div class="main-content settings steam-settings"><div class="group">'+settingRow('monitor','启动模式',pm,'mode-settings')+settingRow('shield','第三方 Steam 服务调用免责声明','','view-legal')+'</div><p class="setting-hint">启动模式在下次新启动 Steam 时生效。<br>恢复已收起的会话时，仍使用当前模式。</p></div>'+gesture()}
function renderProfile(){return stamp()+bar('我的','library')+'<div class="main-content profile"><div class="avatar">'+ic('user')+'</div><h2 style="font-size:22px;margin:0 0 25px">盖世玩家</h2><div class="group">'+settingRow('gear','设置','','settings')+settingRow('download','下载任务','','',true)+'</div></div>'+navPortrait()+gesture()}
function host(){return '<div class="host"><button data-action="library" aria-label="返回盖世游戏">'+ic('back')+'盖世游戏</button><span class="mode-pill">'+(state.currentMode==='gamepad'?'大屏模式':'窗口模式')+'</span><button data-action="settings" aria-label="Steam设置">'+ic('gear')+'</button></div>'}
function steamLibrary(){if(state.emptyLibrary)return '<div class="empty-library">'+ic('grid')+'<p>暂无游戏</p></div>';let cards='<div class="kicker">最近游玩</div><h2>你的游戏，随时继续。</h2><div class="steam-cards">'+games.map(g=>'<button class="steam-card" data-action="game-detail" data-game="'+g.id+'"><img src="'+ASSETS[g.id]+'" alt="'+g.name+'封面"><span>'+g.name+'</span></button>').join('')+'</div>';if(state.currentMode==='window')return '<div class="window-library"><aside class="window-sidebar"><div class="sidebar-heading">主页</div><div>全部游戏</div>'+games.map(g=>'<button data-action="game-detail" data-game="'+g.id+'">'+g.name+'</button>').join('')+'</aside><section class="window-library-main">'+cards+'</section></div>';return cards}
function steamInner(){if(state.steamPage==='friends')return '<h2>好友与聊天</h2><div class="friends-card"><div class="friend-avatar">P</div><div><strong>演示好友</strong><small>在线</small></div></div><div class="native-note" style="margin-top:16px">已定位至 Steam 好友页面。<br>好友消息与语音由 Steam 原生能力承接。</div>'+(state.pendingTarget==='invite'?'<div class="native-note" style="margin-top:15px">游戏邀请 · 艾尔登法环<br><button class="native-secondary" data-action="launch-game" style="margin-top:10px">接受游戏邀请</button></div>':'');
if(state.steamPage==='workshop')return '<h2>创意工坊</h2><div class="workshop-neutral">STEAM WORKSHOP</div><div class="native-note">Steam 原生创意工坊<br>此处为工坊入口落点示意。<br>正式接入需携带支持创意工坊的目标 AppID。</div>';
if(state.steamPage==='detail'){let g=games.find(g=>g.id===state.game);return '<div class="detail-layout"><img class="detail-hero" src="'+ASSETS[g.id]+'" alt="'+g.name+'封面"><div class="detail-body"><div class="kicker">已安装</div><h2>'+g.name+'</h2><button class="playbtn" data-action="launch-game">开始游戏</button><p class="muted" style="font-size:11px;margin-top:17px">通过盖世游戏运行</p>'+(state.gameStatus==='waiting'?'<div class="native-note">正在等待游戏启动结果…</div>':state.gameStatus==='error'?'<div class="err">游戏未能启动，当前页面已保留。<button class="native-secondary" data-action="launch-game" style="margin-top:10px">重试</button></div>':state.gameStatus==='ack'?'<div class="native-note">已收到演示启动回执。<br>本 Demo 不运行真实游戏。</div>':'')+'</div></div>'}
if(state.steamPage==='store')return '<h2>Steam 商店</h2><div class="native-note">由 Steam 原生商店承接。<br>本 Demo 不进行购买或支付。</div><img class="workshop-hero" style="margin-top:20px;height:180px;width:100%" src="'+ASSETS.cyber+'" alt="游戏封面">';
if(state.steamPage==='expired')return '<h2>内容暂不可用</h2><div class="native-note">该通知对应的内容已失效。你可以返回 Steam 游戏库继续浏览。</div><button class="native-secondary" style="margin-top:18px" data-action="steam-library">返回游戏库</button>';
if(state.steamPage==='launch'){return '<h2>游戏启动</h2><div class="native-note">'+(state.gameStatus==='waiting'?'正在等待盖世游戏启动结果…':state.gameStatus==='error'?'游戏启动失败，邀请上下文已保留。':'已收到演示启动回执，本 Demo 不运行真实游戏。')+'</div>'+(state.gameStatus==='error'?'<button class="native-secondary" style="margin-top:18px" data-action="launch-game">重试</button>':'')}
return steamLibrary()}
__LOGIN_FUNCTIONS__
function showLogin(){state.loginPending=false;state.qrStatus='ready';state.loginMethod='password';state.error='';transition('login')}
function submitLogin(){if(state.loginPending||!state.loginUser.trim()||!state.loginPassword)return;if(pref.flowVersion!==FLOW_VERSION||pref.accepted!==LEGAL_VERSION){enter();return}state.loginMethod='password';state.loginPending=true;state.error='';render()}
function refreshQR(){stopTimer();state.qrStatus='loading';state.loginPending=false;state.error='';render();state.timer=setTimeout(()=>{if(state.page==='login'){state.qrStatus='ready';render()}},600)}
function renderSteam(){let big=state.currentMode==='gamepad';let content=state.page==='login'?renderLogin():steamInner();return host()+'<section class="steam '+(big?'steam-big':'steam-window')+'" style="zoom:'+(state.scale/100)+'">'+(big?'<div class="big-top">'+ic('grid')+'<strong>Steam</strong><span class="right">09:41　 Wi-Fi</span></div>':'<div class="steam-top"><span class="logo">'+STEAM+'Steam</span><span>查看</span><span>好友</span><span>游戏</span></div>')+(state.page!=='login'?(big?'<div class="steam-content"><div class="big-tabs"><button class="native-secondary" data-action="steam-library" style="border:0;padding:0;background:none;color:white">游戏库</button><span>最近游玩</span><span>全部游戏</span></div>'+content+'</div><div class="big-bottom"><span><i class="keycap">Enter</i>选择</span><span><i class="keycap">Esc</i>返回</span></div>':'<div class="steam-tabs"><button data-action="steam-store" class="'+(state.steamPage==='store'?'active':'')+'">商店</button><button data-action="steam-library" class="'+(['library','detail'].includes(state.steamPage)?'active':'')+'">库</button><button disabled>社区</button></div><div class="steam-content">'+content+'</div><div class="steam-bottom"><span>＋ 添加游戏</span><span>管理下载</span><button data-action="friends">好友与聊天</button></div>'):'<div class="steam-content">'+content+'</div>')+'</section>'+renderBubble()+renderLandingGuide()}
