function beginPrepare(){stopTimer();state.prepareHidden=false;state.page='prepare';if(state.prepareActive){render();if(!prepareTimer)resumePreparation();return}if(pref.prepared){setStage('starting');return}if(state.progress>=100){setStage('verifying');return}if(state.progress>0){startDownload();return}setStage('metadata')}
