function steamReady(){stopPrepareTimer();state.prepareActive=false;if(state.prepareHidden){state.stage='ready';render();return}stopTimer();if(state.scenario==='login')invalidateSteamAccount();if(!state.loggedIn){showLogin();return}fulfillTarget()}
