document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el||el.disabled)return;if(el.closest('#screen'))previewFrozen=false;if(el.id==='floatingBall'&&Date.now()<ignoreBallClick)return;actions[el.dataset.action]?.(el)});
