function bindBall(){const ball=document.getElementById('floatingBall');if(!ball)return;let drag=null;ball.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();drag={x:e.clientX,y:e.clientY,start:ball.getBoundingClientRect(),moved:false};ball.setPointerCapture(e.pointerId)});ball.addEventListener('pointermove',e=>{if(!drag)return;if(Math.abs(e.clientX-drag.x)+Math.abs(e.clientY-drag.y)>5)drag.moved=true;if(drag.moved){e.preventDefault();const r=screen.getBoundingClientRect();ball.style.right='auto';ball.style.left=Math.max(3,Math.min(r.width-drag.start.width-3,drag.start.left-r.left+e.clientX-drag.x))+'px';ball.style.top=Math.max(44,Math.min(r.height-drag.start.height-11,drag.start.top-r.top+e.clientY-drag.y))+'px'}});ball.addEventListener('pointerup',e=>{if(!drag)return;const moved=drag.moved||Math.abs(e.clientX-drag.x)+Math.abs(e.clientY-drag.y)>5;if(moved){const r=screen.getBoundingClientRect();state.bubbleSide=e.clientX<r.left+r.width/2?'left':'right';const top=drag.start.top-r.top+e.clientY-drag.y;state.bubbleY=Math.max(.08,Math.min(.85,top/(r.height-80)));ignoreBallClick=Date.now()+350;state.bubbleOpen=false;drag=null;render()}else drag=null});ball.addEventListener('pointercancel',()=>{drag=null;render()})}
